package backend

import (
	"context"
	"errors"
	"fmt"
	"math/rand"
	"sort"
	"strings"
	"sync"
	"time"

	"strix-halo-vulkan/ace/lm"
	"strix-halo-vulkan/ace/pipeline"
	"strix-halo-vulkan/ace/plan"
	"strix-halo-vulkan/api"
	"strix-halo-vulkan/vk"
)

// MusicOptions is what cmd/serve's flags come to.
type MusicOptions struct {
	// Models is the checkpoint root: acestep-v15-xl-turbo/, Ace-Step1.5/vae,
	// Qwen3-Embedding-0.6B/ and acestep-5Hz-lm-4B/ under it.
	Models string
	// Device is required.
	Device *Device
	// NoLM leaves the 5 Hz LM out (8 GB of weights and 1.8 GB of KV
	// cache): the DiT-only path, and a thinking request is a 400.
	NoLM bool
	// ID is the model id this backend answers to.
	ID string
}

const defaultMusicModelID = "acestep-v15-xl-turbo"

// Music is the ACE-Step 1.5 adapter: an api.MusicBackend over ace/pipeline
// (MUSIC.md A9).
//
// **Everything is resident** (A-o4): the DiT, its encoders, the VAE, the
// text encoder and the LM with its cache, ~21 GB. Staging them is ~15 s and
// a 60 s song is 26 s, so staging per request would be most of it.
//
// **The device is shared a step at a time.** A request holds it only
// between yields: after every LM step (~50 ms) and every DiT forward
// (0.1-2.4 s by length), so speech waits for one of those, not the song.
type Music struct {
	opt  MusicOptions
	id   string
	pipe *pipeline.Pipeline

	mu  sync.Mutex // rng
	rng *rand.Rand
}

// NewMusic stages the models on the device.
func NewMusic(opt MusicOptions) (*Music, error) {
	if opt.ID == "" {
		opt.ID = defaultMusicModelID
	}
	if opt.Device == nil {
		return nil, fmt.Errorf("backend: the music pipeline needs a device; there is no host path for it")
	}
	b := &Music{opt: opt, id: opt.ID, rng: rand.New(rand.NewSource(rand.Int63()))}
	err := opt.Device.Do(func(d *vk.Device) error {
		p, err := pipeline.New(d, pipeline.DefaultDirs(opt.Models), plan.MaxSeconds)
		if err != nil {
			return err
		}
		if !opt.NoLM {
			if err := p.LoadLM(d, pipeline.LMDir(opt.Models), lm.DefaultOptions()); err != nil {
				p.Destroy()
				return err
			}
		}
		b.pipe = p
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("backend: loading ACE-Step from %s: %w", opt.Models, err)
	}
	return b, nil
}

// Models reports the one model this backend serves.
func (b *Music) Models() []api.Model {
	return []api.Model{{ID: b.id, Object: "model", OwnedBy: "local"}}
}

// formats is pipeline.Formats' keys, sorted.
func formats() []string {
	var out []string
	for f := range pipeline.Formats {
		out = append(out, f)
	}
	sort.Strings(out)
	return out
}

// MusicInfo is what a request may ask for.
func (b *Music) MusicInfo() api.MusicInfo {
	return api.MusicInfo{MinSeconds: plan.MinSeconds, MaxSeconds: plan.MaxSeconds,
		FallbackSeconds: plan.FallbackSeconds, SampleRate: plan.SampleRate, Formats: formats(),
		Thinking: b.pipe.LM != nil, Steps: len(plan.Schedule(plan.DefaultShift, nil))}
}

// Close frees the device objects. The job queue must be closed first.
func (b *Music) Close() {
	b.opt.Device.Do(func(*vk.Device) error {
		b.pipe.Destroy()
		return nil
	})
}

// request is the pipeline's request for an API one.
func musicRequest(req *api.MusicRequest) *plan.Request {
	return &plan.Request{Caption: req.Caption, Lyrics: req.Lyrics, BPM: req.BPM, KeyScale: req.KeyScale,
		TimeSignature: req.TimeSignature, Duration: req.Duration, Language: req.Language}
}

var validTimesigs = map[string]bool{"2": true, "3": true, "4": true, "6": true,
	"2/4": true, "3/4": true, "4/4": true, "6/8": true}

func unsupported(format string, args ...any) error {
	return fmt.Errorf(format+": %w", append(args, api.ErrUnsupported)...)
}

// PlanMusic validates a request and resolves its seeds, format and, when
// given, its length. Nothing touches the device; the LM's prompt is
// tokenised to check it fits the cache with the codes behind it.
func (b *Music) PlanMusic(req *api.MusicRequest) (*api.MusicPlan, error) {
	if req.Thinking && b.pipe.LM == nil {
		return nil, unsupported("thinking needs the 5 Hz LM, which this server did not load (-music-lm)")
	}
	if req.Sample {
		if b.pipe.LM == nil {
			return nil, unsupported("sample mode needs the 5 Hz LM, which this server did not load (-music-lm)")
		}
		if !b.pipe.LM.HasGenres() {
			return nil, unsupported("sample mode needs upstream's genres vocabulary (models/%s): %v", lm.GenresFile, b.pipe.GenresErr)
		}
	}
	if req.Duration != 0 && (req.Duration < plan.MinSeconds || req.Duration > plan.MaxSeconds) {
		return nil, unsupported("duration %g s is outside %d-%d s", req.Duration, plan.MinSeconds, plan.MaxSeconds)
	}
	if req.BPM != 0 && (req.BPM < 30 || req.BPM > 300) {
		return nil, unsupported("bpm %d is outside 30-300", req.BPM)
	}
	if ts := strings.TrimSpace(req.TimeSignature); ts != "" && !validTimesigs[ts] {
		return nil, unsupported("time signature %q: 2, 3, 4 or 6 (or 2/4, 3/4, 4/4, 6/8)", req.TimeSignature)
	}
	if req.Language != "" {
		ok := false
		for _, l := range lm.ValidLanguages {
			ok = ok || l == req.Language
		}
		if !ok {
			return nil, unsupported("vocal language %q is not one the model knows (%s)", req.Language,
				strings.Join(lm.ValidLanguages, ", "))
		}
	}
	format := req.Format
	if format == "" {
		format = "mp3"
	}
	if _, ok := pipeline.Formats[format]; !ok {
		return nil, unsupported("audio format %q: %s", req.Format, strings.Join(formats(), ", "))
	}
	if req.Shift != 0 && (req.Shift < 1 || req.Shift > 5) {
		return nil, unsupported("shift %g is outside 1-5", req.Shift)
	}
	if v := req.LMTemperature; v != nil && *v < 0 {
		return nil, unsupported("lm_temperature %g is negative", *v)
	}
	if v := req.LMCFGScale; v != nil && *v < 1 {
		return nil, unsupported("lm_cfg_scale %g is below 1", *v)
	}
	if v := req.LMTopP; v != nil && (*v <= 0 || *v > 1) {
		return nil, unsupported("lm_top_p %g is outside (0, 1]", *v)
	}
	p := &api.MusicPlan{Format: format, Steps: len(plan.Schedule(cmpOr(req.Shift, plan.DefaultShift), req.Timesteps))}
	// Drawn seeds are 32-bit, as upstream draws them: a client in
	// JavaScript reads a JSON number past 2^53 wrong, and could not replay
	// the song it was given the seed of.
	b.mu.Lock()
	p.Seed, p.LMSeed = int64(b.rng.Uint32()), int64(b.rng.Uint32())
	b.mu.Unlock()
	if req.Seed != nil {
		p.Seed = *req.Seed
	}
	if req.LMSeed != nil {
		p.LMSeed = *req.LMSeed
	}
	r := musicRequest(req)
	switch {
	case req.Duration > 0:
		p.Seconds = float64(musicLatents(r, req.Thinking)*plan.Hop) / plan.SampleRate
	case !req.Thinking:
		p.Seconds = plan.FallbackSeconds
	}
	if req.Thinking && !req.Sample {
		// The codes phase's prompt is the CoT's plus the CoT, and the codes
		// follow it in the same cache. (Sample mode's lyrics are not known
		// yet; the codes phase checks its own fit when it starts.)
		secs := cmpOr(p.Seconds, plan.MaxSeconds)
		need, err := b.pipe.LM.Positions(r.Caption, r.Lyrics, secs)
		if err != nil {
			return nil, err
		}
		if need > b.pipe.LM.MaxLen() {
			return nil, unsupported("the LM would need up to %d positions for %.0f s of codes after these lyrics, and holds %d; shorten the lyrics or the song",
				need, secs, b.pipe.LM.MaxLen())
		}
	}
	p.Estimate = musicEstimate(r, req.Thinking, req.Sample, cmpOr(p.Seconds, 120)).total()
	return p, nil
}

func cmpOr(a, b float64) float64 {
	if a != 0 {
		return a
	}
	return b
}

// musicLatents is the latent length a request with a duration runs at:
// the codes' when thinking (5 a second, int(duration·5) of them), the
// request's own otherwise.
func musicLatents(r *plan.Request, thinking bool) int {
	if thinking {
		return max(plan.MinLatents, lm.CodesPerSecond*int(r.Duration*lm.CodesPerSecond))
	}
	return r.LatentLength()
}

// musicCost is a request's expected wall time by stage, from MUSIC.md's
// measurements with the device to itself: an LM step is 50 ms (A7), a CoT
// ~150 of them; a DiT forward is 2.65e-4·L + 7.16e-9·L² s over L = 12.5 a
// second tokens (A3's 0.86 s at 3,000 and 2.39 s at 7,500) plus 35 ms of
// host; the VAE is 10.4 ms a second of audio (A6); encoding the file is
// ffmpeg's. Sample mode's pass is ~sampleSteps (a caption, the metas and
// a song's lyrics), and the song it writes usually has every meta, so
// phase 1 is then skipped.
type musicCost struct {
	sample, think, codes, dit, vae, write time.Duration
}

const sampleSteps = 450

func (c musicCost) total() time.Duration {
	return c.sample + c.think + c.codes + c.dit + c.vae + c.write
}

func musicEstimate(r *plan.Request, thinking, sample bool, seconds float64) musicCost {
	sec := func(s float64) time.Duration { return time.Duration(s * float64(time.Second)) }
	var c musicCost
	if sample {
		c.sample = sec(sampleSteps * 0.050)
	}
	if thinking {
		if !sample && !lm.UserMeta(r).HasAll() {
			c.think = sec(150 * 0.050)
		}
		c.codes = sec((seconds*lm.CodesPerSecond + 1) * 0.050)
	}
	L := seconds * 12.5
	c.dit = sec(8 * (2.65e-4*L + 7.16e-9*L*L + 0.035))
	c.vae = sec(0.0104*seconds + 0.1)
	c.write = sec(0.004 * seconds)
	return c
}

// GenerateMusic runs a planned request and writes the audio to dst.
func (b *Music) GenerateMusic(ctx context.Context, req *api.MusicRequest, mp *api.MusicPlan, dst string, progress func(api.MusicProgress)) error {
	r := musicRequest(req)
	secs := cmpOr(mp.Seconds, 120)
	c := musicEstimate(r, req.Thinking, req.Sample, secs)
	var sampling *lm.Sampling
	if req.LMTemperature != nil || req.LMCFGScale != nil || req.LMTopP != nil {
		s := lm.DefaultSampling
		if v := req.LMTemperature; v != nil {
			s.Temperature = *v
		}
		if v := req.LMCFGScale; v != nil {
			s.CFG = float32(*v)
		}
		if v := req.LMTopP; v != nil {
			s.TopP = *v
		}
		sampling = &s
	}
	frac := func(stage string, done, total int) float64 {
		t := c.total().Seconds()
		part := func(d time.Duration, done, total int) float64 {
			if total <= 0 {
				return 0
			}
			return d.Seconds() * float64(min(done, total)) / float64(total)
		}
		switch stage {
		case "sample":
			return part(c.sample, done, sampleSteps) / t
		case "think":
			return (c.sample.Seconds() + part(c.think, done, 150)) / t
		case "codes":
			return (c.sample+c.think).Seconds()/t + part(c.codes, done, total)/t
		case "dit":
			return (c.sample+c.think+c.codes).Seconds()/t + part(c.dit, done, total)/t
		case "vae":
			return (c.sample + c.think + c.codes + c.dit).Seconds() / t
		}
		return 0
	}
	var smp *pipeline.Sample
	if req.Sample {
		smp = &pipeline.Sample{Query: req.SampleQuery, SkipCoT: req.SampleMode}
	}
	var song *lm.Song
	var res *pipeline.Result
	err := b.opt.Device.Do(func(*vk.Device) error {
		var err error
		res, err = b.pipe.Generate(r, pipeline.Options{
			Seed: uint64(mp.Seed), Think: req.Thinking, LMSeed: uint64(mp.LMSeed), Sampling: sampling, Sample: smp,
			Shift: req.Shift, Timesteps: req.Timesteps,
			Between: func() error {
				if err := ctx.Err(); err != nil {
					return err
				}
				b.opt.Device.yield()
				return nil
			},
			Progress: func(stage string, done, total int) {
				progress(api.MusicProgress{Stage: stage, Fraction: frac(stage, done, total)})
			},
			Sampled: func(s lm.Song) {
				song = &s
				progress(api.MusicProgress{Stage: "sampled", Fraction: frac("think", 0, 1),
					Plan: &api.MusicMetadata{Caption: s.Caption, Lyrics: s.Lyrics, Genres: s.Genres, BPM: s.BPM,
						KeyScale: s.KeyScale, TimeSignature: s.TimeSignature, Duration: s.Duration,
						Language: cmpStr(s.Language, "unknown")}})
			},
			Planned: func(d *plan.Request, seconds float64) {
				// The plan fixes the length, so the estimate is redone
				// around it; what is spent is kept.
				spent, sampled := c.think, c.sample
				c = musicEstimate(d, req.Thinking, req.Sample, seconds)
				c.think, c.sample = spent, sampled
				m := &api.MusicMetadata{Caption: d.Caption, BPM: d.BPM, KeyScale: d.KeyScale,
					TimeSignature: d.TimeSignature, Duration: seconds, Language: cmpStr(d.Language, "unknown")}
				if song != nil {
					m.Lyrics, m.Genres = d.Lyrics, song.Genres
				}
				progress(api.MusicProgress{Stage: "planned", Fraction: frac("codes", 0, 1), Seconds: seconds,
					Estimate: c.total(), Plan: m})
			},
		})
		return err
	})
	if err != nil {
		if errors.Is(err, context.Canceled) {
			return err
		}
		return fmt.Errorf("ace: %w", err)
	}
	progress(api.MusicProgress{Stage: "write", Fraction: 1 - c.write.Seconds()/c.total().Seconds()})
	return pipeline.Write(dst, res.Audio)
}

func cmpStr(a, b string) string {
	if a != "" {
		return a
	}
	return b
}
package backend

import (
	"context"
	"errors"
	"fmt"
	"image"
	"image/color"
	"image/draw"
	"math/rand"
	"sync"

	"strix-halo-vulkan/api"
	"strix-halo-vulkan/qimage/pipeline"
	qvae "strix-halo-vulkan/qimage/vae"
	"strix-halo-vulkan/vk"
	"strix-halo-vulkan/zimage/qwen"
)

// ImageOptions is what cmd/serve's flags come to.
type ImageOptions struct {
	// Model is the Qwen-Image-2.1 checkpoint root, holding transformer/,
	// text_encoder/, vae/, processor/ and scheduler/.
	Model string
	// Device is required: there is no host path for this pipeline. The DiT is
	// 2.27 s a step on the device and hours on the host, so a CPU fallback
	// would not be a slow answer, it would be a timeout.
	Device *Device
	// Width and Height are the largest image the arenas are built for, and the
	// size a request that names none gets.
	//
	// This is a residency decision and the only one this vertical has. The
	// arenas are ~27 GB, they are allocated once, and every smaller image runs
	// inside them -- so what this number buys is the ceiling and nothing else.
	//
	// **What a request has to fit inside is this rectangle's area, not its
	// sides.** Every arena here is sized by the pixel count alone (measured:
	// `qimage/vae`'s TestArenaShape), so a server started at 1024x1024 serves
	// 1344x768 and 2048x512 as readily as its own square, and a 16:9 request
	// gets 16:9's share of the arenas instead of 56% of it.
	//
	// **The area has a hard limit of 1,403,584 pixels** -- 1184x1184, or
	// 1536x864 at 16:9 -- and it is not a budget: the VAE decoder's
	// activation arena is one storage buffer and this device caps one at
	// 4 GiB - 4 (IMAGE.md Q5g/Q6). Anything larger is refused at startup,
	// naming the number.
	Width, Height int
	// Steps is the schedule a request that names none gets. Unlike
	// Z-Image-Turbo's 8, Qwen-Image-2.1 is not a distillation and 40 is what
	// diffusers runs.
	Steps int
	// MaxPrompt is the longest prompt the text encoder is built for.
	MaxPrompt int
	// Refs is how many reference images an edit may carry, and zero means
	// this server does not answer /v1/images/edits at all.
	//
	// It is residency, which is why it is a number and not a bool. Editing
	// stages two more models -- the 27-layer vision tower and the VAE's
	// encoder, ~1.4 GB together -- and every reference then adds its latent
	// rows to the transformer's prefix and its own share of the prefix KV
	// cache, which at one 1024² reference is ~2.1 GB. Ten of them is the
	// model's limit and a different machine's decision.
	//
	// There is no Preview field: TAEQI2.1, the preview decoder, is 29 MB of
	// weights and 224 MB of activation arena at a 1024² ceiling, which is
	// too little residency to be worth a switch, so previews are always on.
	// Its checkpoint is `taeqi2_1/` beside Model.
	Refs int
	// CondSize is the square whose *area* every reference image is resized
	// to before it is encoded, and the default output size of an edit that
	// names none. It is diffusers' `output_resolution`; zero takes the
	// model's own default of 1024.
	CondSize int
	// ID is the model id this backend answers to in /v1/models.
	ID string
	// FP16 stages the text encoder and the transformer as fp16 rather than
	// the int8 banks: the control (research/qimage-vertical.md Q13).
	FP16 bool
}

const (
	defaultImageModelID = "qwen-image-2.1"
	// maxPartialImages bounds `partial_images`, and it is past OpenAI's 3 on
	// purpose. A frame at 1024² is ~63 ms of TAEQI2.1 on the device plus
	// encoding the PNG (~60 ms) and writing it to a client -- ~130 ms,
	// serial with the steps, so sixteen are ~2 s of an 89 s image (~2.3%).
	// A client written against OpenAI never asks for more than 3 and pays
	// nothing for the headroom.
	maxPartialImages = 16
)

// Image is the Qwen-Image-2.1 adapter: an api.ImageBackend over
// qimage/pipeline.
//
// **It is resident, and the resolution is not part of what is resident.**
// Construction stages ~7.8 GB of text encoder, ~7.5 GB of transformer (int8
// banks; 13.2 and 13.3 as fp16, research/qimage-vertical.md Q13) and ~1.0 GB
// of VAE, sizes the activation arenas for the largest image the flags
// asked for, and then every request is arithmetic: the transformer states its
// run length per image, the VAE re-records its graph from the latent it is
// handed. So a 512x512 request out of a 1024x1024 server costs a quarter of
// the tokens and stages nothing.
//
// One mutex guards the pipeline, and it is a correctness lock rather than a
// contention one: the DiT's prefix KV cache and both activation arenas are
// one image's, so two interleaved would not be slower, they would be one
// image.
type Image struct {
	opt ImageOptions
	id  string

	mu   sync.Mutex
	pipe *pipeline.Pipeline
	// rng draws a seed for a request that named none. It is here rather than
	// in the handler because the seed that was used is part of what the model
	// produced -- a client asking for the same image again sends it back.
	rng *rand.Rand
}

// NewImage stages the whole pipeline on the device.
func NewImage(opt ImageOptions) (*Image, error) {
	if opt.ID == "" {
		opt.ID = defaultImageModelID
	}
	if opt.Device == nil {
		return nil, fmt.Errorf("backend: the image pipeline needs a device; there is no host path for it")
	}
	b := &Image{opt: opt, id: opt.ID, rng: rand.New(rand.NewSource(rand.Int63()))}
	bank := qwen.BankQ8
	if opt.FP16 {
		bank = qwen.BankFP16
	}
	err := opt.Device.Do(func(dev *vk.Device) error {
		p, err := pipeline.New(dev, pipeline.Options{
			Model: opt.Model, Width: opt.Width, Height: opt.Height,
			Steps: opt.Steps, MaxPrompt: opt.MaxPrompt,
			Refs: opt.Refs, CondSize: opt.CondSize, Bank: bank,
		})
		if err != nil {
			return err
		}
		b.pipe = p
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("backend: loading %s: %w", opt.Model, err)
	}
	return b, nil
}

// Models reports the one model this backend serves.
func (b *Image) Models() []api.Model {
	return []api.Model{{ID: b.id, Object: "model", OwnedBy: "local"}}
}

// Geometry is what this process was started for.
func (b *Image) Geometry() api.ImageGeometry {
	w, h := b.pipe.Size()
	// Previews are unconditional -- the tiny decoder is always staged -- so unlike under Z-Image there is no flag for the two
	// fields to disagree about. Edits report the *count* rather than a
	// strength, because 2.1 has no strength: a client reads MaxRefs to know
	// how many pictures it may send.
	return api.ImageGeometry{
		Width: w, Height: h,
		MaxPixels:   b.pipe.MaxPixels(),
		Multiple:    pipeline.SizeMultiple,
		Steps:       b.pipe.Steps(),
		Previews:    true,
		MaxPartials: maxPartialImages,
		Edits:       b.pipe.Refs() > 0,
		MaxRefs:     b.pipe.Refs(),
	}
}

// Residency reports what the pipeline holds on the device, for the startup
// banner.
func (b *Image) Residency() (encoder, transformer, vaeWeights, activations int) {
	return b.pipe.Residency()
}

// EditResidency is what the edit half holds: the vision tower's and the VAE
// encoder's weights, and the transformer's prefix KV cache. Zero when this
// server does not edit.
func (b *Image) EditResidency() (weights, cache int) { return b.pipe.EditResidency() }

// Close releases the device residency.
func (b *Image) Close() {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.pipe == nil {
		return
	}
	_ = b.opt.Device.Do(func(*vk.Device) error {
		b.pipe.Destroy()
		b.pipe = nil
		return nil
	})
}

