// transparentPrefix and transparentSuffix are the model card's recommended
// phrasing for an RGBA image, verbatim. Transparency in this model is asked
// for in the *prompt* -- the VAE emits four channels either way -- so
// `background: "transparent"` is a prompt rewrite plus a decision about the
// alpha plane, and not a mode.
const (
	transparentPrefix = "This is an RGBA image with transparency. "
	transparentSuffix = " The image has alpha channel and the background is transparent."
)

// Generate renders one image.
//
// **The device lock is held for the whole run, and the context is what cuts
// it short.** A denoising *step* is a submit-and-fence with nothing to
// abandon inside it, but between two steps there is nothing in flight, and
// the same is true between the VAE's submit batches. So the context reaches
// all the way down (`pipeline.Run`, `Edit`, `Decode`, and the vision tower
// and VAE encoder an edit runs first) and a client that hangs up stops paying
// within one step — about 2.2 s of a 92 s image, or a quarter-second of the
// decode — instead of paying for the whole picture.
//
// That matters past the wasted arithmetic: Device.Do is one lock for every
// vertical in the process, so an abandoned image used to block the queued
// speech and embedding requests behind it for its full duration too.
func (b *Image) Generate(ctx context.Context, req *api.ImageRequest) (*api.ImageResult, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if b.pipe == nil {
		return nil, fmt.Errorf("the image pipeline is closed")
	}

	if len(req.Init) > 0 && b.pipe.Refs() == 0 {
		return nil, fmt.Errorf("this server was not started for editing; restart it with -edits N: %w",
			api.ErrUnsupported)
	}

	seed := int64(0)
	if req.Seed != nil {
		seed = *req.Seed
	} else {
		seed = b.rng.Int63()
	}

	// The geometry is validated before the device is touched, so a bad size
	// costs a comparison rather than a text encoder run. The handler has
	// already checked the same thing against Geometry(); this is the check
	// that is true by construction rather than by agreement, and it is also
	// how the resolved size is read back for a request that named one side or
	// neither.
	//
	// An edit may name neither, and then the size is *not* the server's
	// default: it is the last reference image's aspect ratio at the model's
	// condition area, which only the pipeline can work out. So zero is
	// passed through rather than resolved here.
	width, height := 0, 0
	if len(req.Init) == 0 || req.Width != 0 || req.Height != 0 {
		_, latentH, latentW, err := b.pipe.LatentFor(req.Width, req.Height)
		if err != nil {
			return nil, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
		}
		width, height = latentW*pipeline.VAEScale, latentH*pipeline.VAEScale
	}

	prompt := req.Prompt
	if req.Transparent {
		prompt = transparentPrefix + prompt + transparentSuffix
	}

	// Which steps a partial comes from. The handler said how many it wants;
	// this is the half that needs the step count, and it is why the decision
	// is here (api.ImageRequest.PartialImages says so).
	steps := req.Steps
	if steps == 0 {
		steps = b.pipe.Steps()
	}
	var (
		partialAt map[int]int
		perr      error
	)
	if req.Partial != nil && req.PartialImages > 0 {
		partialAt = partialSteps(0, steps, min(req.PartialImages, maxPartialImages))
	}
	var progress func(pipeline.Step)
	if len(partialAt) > 0 {
		progress = func(st pipeline.Step) {
			idx, want := partialAt[st.Index]
			// A frame the client could not take stops any *further* frames.
			// It does not stop the run: a denoising step is a
			// submit-and-fence with no cancellation point in it.
			if !want || perr != nil || st.Preview == nil {
				return
			}
			t, err := st.Preview()
			if err != nil {
				perr = fmt.Errorf("preview at step %d: %w", st.Index, err)
				return
			}
			// A preview takes the finished image's alpha policy. Under the
			// fitted matrix it was always opaque, because that alpha was the
			// least reliable of its four channels; TAEQI2.1's lands rms
			// 0.0034 from the full VAE's, so a transparent request now sees
			// the holes it will get. The frame is already the finished
			// image's size -- the tiny decoder is 16x, like the real one.
			frame := pipeline.ToImage(t, !req.Transparent)
			w, h := t.W, t.H
			drawProgress(frame, st.Index+1, steps)
			perr = req.Partial(api.ImagePartial{
				Index: idx, Step: st.Index, Steps: steps,
				Image: frame,
				Width: w, Height: h,
			})
		}
	}

	var (
		img *qvae.Tensor
		tm  *pipeline.Timings
	)
	refs, err := nrgbaRefs(req.Init)
	if err != nil {
		return nil, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	err = b.opt.Device.Do(func(*vk.Device) error {
		var err error
		if len(refs) > 0 {
			img, tm, err = b.pipe.Edit(ctx, pipeline.EditRequest{
				Prompt: prompt, Images: refs, Width: width, Height: height,
				Steps: req.Steps, Seed: seed, Progress: progress,
			})
			return err
		}
		img, tm, err = b.pipe.Run(ctx, pipeline.Request{
			Prompt: prompt, Width: width, Height: height,
			Steps: req.Steps, Seed: seed, Progress: progress,
		})
		return err
	})
	// A frame the client could not be given -- they hung up -- is the
	// failure, not whatever the rest of the run did, so it is reported first.
	if perr != nil {
		return nil, perr
	}
	if err != nil {
		// A prompt past the text encoder's arena is the client's fault and
		// fixable by them.
		if errors.Is(err, pipeline.ErrPromptTooLong) {
			return nil, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
		}
		return nil, err
	}

	return &api.ImageResult{
		// The alpha plane is kept only when the caller asked for
		// transparency. It exists either way -- the VAE has four channels --
		// but on an ordinary prompt it is whatever the model painted there,
		// and compositing over white is what makes an opaque request opaque.
		Image:  pipeline.ToImage(img, !req.Transparent),
		Width:  tm.Width,
		Height: tm.Height,
		Steps:  len(tm.Steps),
		Seed:   seed,
	}, nil
}

// drawProgress paints a red bar along the bottom edge of an in-progress
// frame, done/steps of the way across -- step 20 of 40 is half the width.
// done counts completed steps, so a frame from step index k passes k+1.
//
// It is drawn on the partial only, never on the finished image, and at the
// frame's full size after the resize so its edge stays hard. The height
// scales with the image (8 px at 1024) so it reads at any size a client
// shows the frame at, with a floor so a small request still gets a visible
// line.
func drawProgress(img *image.NRGBA, done, steps int) {
	if steps <= 0 || done <= 0 {
		return
	}
	b := img.Rect
	width := b.Dx() * min(done, steps) / steps
	height := max(4, b.Dy()/128)
	bar := image.Rect(b.Min.X, b.Max.Y-height, b.Min.X+width, b.Max.Y).Intersect(b)
	draw.Draw(img, bar, image.NewUniform(color.NRGBA{R: 255, A: 255}), image.Point{}, draw.Src)
}

// partialSteps picks which denoising steps an in-progress frame comes from:
// n frames spread evenly over the steps that will run, as a map from step
// index to the frame's own index.
//
// **The first frame is always the first step's.** A client should see
// something as soon as there is something to see, and step 0's denoised
// estimate already carries the composition and colour, only fuzzy. Nothing
// earlier is worth a frame: before the first step the latent is the seeded
// noise, and the preview decoder maps that to grey static. The rest follow at
// run/n intervals, so with the finished image counted as frame n+1 the
// spacing is even all the way to the end.
//
// It is host arithmetic with three edges -- fewer steps than frames asked
// for, a one-step schedule, and the last step -- and none of them would show
// up in an image, which is why it has a test of its own. It survived the
// migration untouched: the policy did not change with the model.
//
// `first` is where the run starts, and under Qwen-Image-2.1 it is 0 for every
// request: an edit conditions on its references rather than starting part-way
// up the schedule, so there is no truncated run to offset. It stays a
// parameter because it is the one thing that would change if a partially
// renoised path ever came back, and because a constant argument at the two
// call sites is cheaper to read than a comment explaining its absence.
//
// The last step is excluded, and that is the only judgement in here. Its
// denoised estimate *is* the final latent -- the terminal sigma is the
// scheduler's shift_terminal -- so a partial there would be the finished
// image sent twice, through two different decoders.
func partialSteps(first, steps, n int) map[int]int {
	run := steps - first
	if run < 2 || n <= 0 {
		return nil
	}
	out := make(map[int]int, n)
	last := steps - 2 // the last step a partial may come from
	idx := 0
	for j := 0; j < n; j++ {
		k := first + j*run/n
		if k > last {
			k = last
		}
		if _, seen := out[k]; seen {
			continue
		}
		out[k] = idx
		idx++
	}
	return out
}

// nrgbaRefs converts the decoded reference images to the 8-bit NRGBA the
// pipeline's resampler and compositor work in.
//
// It is a conversion and not a resize: the resize is the *model's*, exact to
// the 8-bit level against Pillow's Lanczos (IMAGE.md Q8.3b), and doing any of
// it here would be a second, worse one. `image.Decode` already hands back
// NRGBA for a PNG with alpha, and this is a copy for everything else --
// including the JPEG case, where the alpha it fills in is opaque, which is
// what a JPEG means.
func nrgbaRefs(in []image.Image) ([]*image.NRGBA, error) {
	if len(in) == 0 {
		return nil, nil
	}
	out := make([]*image.NRGBA, len(in))
	for i, src := range in {
		b := src.Bounds()
		if b.Dx() <= 0 || b.Dy() <= 0 {
			return nil, fmt.Errorf("reference image %d is empty", i)
		}
		if n, ok := src.(*image.NRGBA); ok && n.Bounds().Min == (image.Point{}) {
			out[i] = n
			continue
		}
		dst := image.NewNRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
		draw.Draw(dst, dst.Bounds(), src, b.Min, draw.Src)
		out[i] = dst
	}
	return out, nil
}
// Package backend holds the model adapters the HTTP API is served from: one
// per vertical, each owning its weights, its device residency and the lock
// that serialises requests against them.
//
// It exists so that `api` can stay a routing layer with no model in it and no
// Vulkan behind it, and so that the adapters are testable and reusable
// outside `cmd/serve`. The direction of the dependency is
// `cmd/serve -> backend -> api`, never the other way: `api` declares the
// interfaces (api.SpeechBackend, api.TranscriptionBackend) and the types here
// satisfy them.
package backend

import (
	"fmt"
	"sync"

	"strix-halo-vulkan/vk"
)

// strixHaloDeviceID is this machine's iGPU (gfx1151 / RADV STRIX_HALO), which
// every command in this repository prefers when it is present.
const strixHaloDeviceID = 0x1586

// Device is the Vulkan device plus the lock that makes it safe to serve from.
//
// **The lock is not a performance choice, it is a correctness one.** A
// vk.Device holds a single queue, and nothing in `vk` is externally
// synchronised: two requests recording and submitting at the same time is
// undefined behaviour and not merely contention. Every run -- and every
// staging pass, which also records and submits -- goes through Do, so the
// server is concurrent at the HTTP layer and serial at the device.
//
// That is also the right shape for the hardware. The models here are sized to
// saturate the iGPU on their own; two of them interleaved would not go
// faster, they would just share a 236 GB/s bus.
type Device struct {
	inst *vk.Instance
	dev  *vk.Device
	mu   fifoLock
}

// fifoLock is a mutex that hands off in arrival order. Device holds one
// rather than a sync.Mutex because of yield: a sync.Mutex lets an unlocking
// goroutine take the lock straight back, and lets a caller finishing one Do
// barge in ahead of an older waiter for its next, so a yield would usually
// hand nothing over, or hand over more than one unit.
type fifoLock struct {
	mu    sync.Mutex
	held  bool
	queue []chan struct{}
}

func (l *fifoLock) Lock() {
	l.mu.Lock()
	if !l.held {
		l.held = true
		l.mu.Unlock()
		return
	}
	ch := make(chan struct{})
	l.queue = append(l.queue, ch)
	l.mu.Unlock()
	<-ch // the lock is handed over held
}

func (l *fifoLock) Unlock() {
	l.mu.Lock()
	defer l.mu.Unlock()
	if !l.held {
		panic("backend: unlock of an unlocked device")
	}
	if len(l.queue) == 0 {
		l.held = false
		return
	}
	close(l.queue[0])
	l.queue = l.queue[1:]
}

// waiters is how many callers are queued for the lock.
func (l *fifoLock) waiters() int {
	l.mu.Lock()
	defer l.mu.Unlock()
	return len(l.queue)
}

// OpenDevice picks this machine's iGPU, or the first device with a compute
// queue, and enables the features every model in this repository is built
// against: fp16, cooperative matrix, and subgroup size control where the
// driver reports it.
func OpenDevice(appName string) (*Device, error) {
	inst, err := vk.NewInstance(appName)
	if err != nil {
		return nil, err
	}
	devices, err := inst.PhysicalDevices()
	if err != nil {
		inst.Destroy()
		return nil, err
	}
	if len(devices) == 0 {
		inst.Destroy()
		return nil, fmt.Errorf("backend: no Vulkan devices")
	}
	phys := &devices[0]
	for i := range devices {
		if devices[i].DeviceID == strixHaloDeviceID {
			phys = &devices[i]
			break
		}
	}
	qf, err := phys.ComputeQueueFamily()
	if err != nil {
		inst.Destroy()
		return nil, err
	}
	sgs, err := phys.SubgroupSizeControl()
	if err != nil {
		inst.Destroy()
		return nil, err
	}
	dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{
		Float16: true, CoopMatrix: true, SubgroupSizeControl: sgs.Supported,
	})
	if err != nil {
		inst.Destroy()
		return nil, err
	}
	return &Device{inst: inst, dev: dev}, nil
}

// Do runs fn with the device held. It is the only way a caller outside this
// package touches the device.
func (d *Device) Do(fn func(*vk.Device) error) error {
	d.mu.Lock()
	defer d.mu.Unlock()
	return fn(d.dev)
}

// yield is called only from inside Do, by a long run that has nothing on the
// device and holds nothing another caller could touch (the vision tower
// between two submits). It lets one waiting Do run before this caller
// continues, and reports whether anyone was waiting. The lock is FIFO, so the
// waiters queued now run first, one Do each, and then this caller, ahead of
// any of theirs that queue again.
func (d *Device) yield() bool {
	if d.mu.waiters() == 0 {
		return false
	}
	d.mu.Unlock()
	d.mu.Lock()
	return true
}

// Name is the physical device's name, for the startup banner.
func (d *Device) Name() string { return d.dev.Physical().Name }

// Close destroys the device and the instance. Every model staged on it must
// already have been destroyed.
func (d *Device) Close() {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.dev.Destroy()
	d.inst.Destroy()
}

